// Centralized state -> slideshow images. The data lives in stateSlides.json, generated by
// scripts/fetch_state_images.py from each state's own places; this module only resolves
// lookups and builds image URLs. Images are served from public/images/states/<state-id>/.
import mapping from "./stateSlides.json";

export const STATE_IDS = Object.keys(mapping);

/** "Tamil Nadu", "tamil-nadu", " TAMIL_NADU " -> "tamil-nadu" */
export function normalizeStateSlug(value) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

// Also accept a state's display name (e.g. "Dadra and Nagar Haveli and Daman and Diu",
// whose id is the shorter "dadra-nagar-haveli-daman-diu").
const ID_BY_KEY = new Map();
for (const id of STATE_IDS) {
  ID_BY_KEY.set(id, id);
  ID_BY_KEY.set(normalizeStateSlug(mapping[id].name), id);
}

/** Canonical state id for a slug or name, or null if the state is unknown. */
export function resolveStateId(value) {
  return ID_BY_KEY.get(normalizeStateSlug(value)) ?? null;
}

const imageUrl = (stateId, slideId, width) => `/images/states/${stateId}/${slideId}-${width}.webp`;

// Memoized so each state's array keeps one identity (the slideshow relies on that).
const cache = new Map();

/** Slides for exactly this state, or [] for an unknown state. Never another state's images. */
export function getStateSlides(value) {
  const id = resolveStateId(value);
  if (!id) return [];
  if (!cache.has(id)) {
    cache.set(
      id,
      mapping[id].slides.map((s) => ({
        id: s.id,
        place: s.place,
        location: s.city,
        credit: s.credit,
        src: imageUrl(id, s.id, s.widths[s.widths.length - 1]),
        srcSet: s.widths.map((w) => `${imageUrl(id, s.id, w)} ${w}w`).join(", "),
      }))
    );
  }
  return cache.get(id);
}

/** Previous/next state in the app's state order, for moving between state pages. */
export function getNeighbourStates(value) {
  const i = STATE_IDS.indexOf(resolveStateId(value));
  if (i === -1) return { previous: null, next: null };
  const at = (j) => {
    const id = STATE_IDS[(j + STATE_IDS.length) % STATE_IDS.length];
    return { id, name: mapping[id].name };
  };
  return { previous: at(i - 1), next: at(i + 1) };
}
